package net.civeira.phylax.features.access.userprofile.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class BirthdateVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property birthdate of user profile ")
  void test_birthdate_v_o_builder() {
    Assertions.assertFalse(BirthdateVO.nullValue().getBirthdate().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(BirthdateVO.tryFrom(null).getBirthdate().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", BirthdateVO.from("one").getBirthdate().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> BirthdateVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", BirthdateVO.from("one").toString());
  }
}
